import {modelBeam} from './model-recipes.js?v=motion-v70';
export const cableDefaults={cableSag:.30,cableSway:.035,cableWind:.4,cableThickness:.018,cableSegments:24,cableSpacing:.13,cableAnchorAX:2.5,cableAnchorAY:5.2,cableAnchorAZ:-5.9,cableAnchorBX:6,cableAnchorBY:5.9,cableAnchorBZ:-5.9,cableColor:'#a3a29b',cableHighlight:'#e0dc60',cableHighlightStrength:.7};
export function cablePoint(u,index,time,input={}){const f={...cableDefaults,...input},s=Math.sin(u*Math.PI),wave=Math.sin(time*f.cableWind+u*4.5+index*.3)*f.cableSway*s;return [f.cableAnchorAX+(f.cableAnchorBX-f.cableAnchorAX)*u,f.cableAnchorAY+(f.cableAnchorBY-f.cableAnchorAY)*u+index*f.cableSpacing-f.cableSag*4*u*(1-u)+wave,f.cableAnchorAZ+(f.cableAnchorBZ-f.cableAnchorAZ)*u+Math.cos(time*f.cableWind+u*3)*f.cableSway*s];}
function blend(a,b,q){const rgb=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)),A=rgb(a),B=rgb(b);return '#'+A.map((v,i)=>Math.round(v+(B[i]-v)*q).toString(16).padStart(2,'0')).join('');}
export function livingCableNodes(time,input={},highlight=0){const f={...cableDefaults,...input},nodes=[],N=Math.max(8,Math.min(64,Math.round(f.cableSegments)));for(let i=0;i<3;i++)for(let j=0;j<N;j++){const u=j/N,v=(j+1)/N,q=highlight*f.cableHighlightStrength*(.6+.4*Math.exp(-(((u-((time*.25)%1))/.3)**2)));const node=modelBeam('cable-'+i+'-'+j,cablePoint(u,i,time,f),cablePoint(v,i,time,f),f.cableThickness,blend(f.cableColor,f.cableHighlight,q));node.material.unlit=q>.4;nodes.push(node);}nodes.push(modelBeam('cable-terminal-support',[f.cableAnchorBX,0,f.cableAnchorBZ],[f.cableAnchorBX,f.cableAnchorBY+f.cableSpacing*2+.25,f.cableAnchorBZ],.065,'#41433d'));for(let i=0;i<3;i++){const a=cablePoint(0,i,time,f);nodes.push(modelBeam('cable-mount-'+i,[a[0]-.07,a[1]-.07,a[2]+.025],[a[0]+.07,a[1]+.07,a[2]+.025],f.cableThickness*3,'#42433e'));}return nodes;}
